python3 - <<'PY'
import gzip, xml.etree.ElementTree as ET
C='{http://linux.duke.edu/metadata/common}'; R='{http://linux.duke.edu/metadata/rpm}'
with gzip.open('/tmp/baseos-primary.xml.gz','rb') as f:
 for _,e in ET.iterparse(f,events=('end',)):
  if e.tag==C+'package':
   n=e.findtext(C+'name'); v=e.find(C+'version')
   if n in ('openssl-libs','openssl-fips-provider','crypto-policies','crypto-policies-scripts') and (n!='openssl-libs' or v.attrib['ver'].startswith('3.5.1')):
    loc=e.find(C+'location').attrib['href']; print(n,v.attrib['ver'],v.attrib['rel'],loc)
    if n=='openssl-libs':
     req=e.find(C+'format/'+R+'requires')
     for x in req or []:
      if x.attrib.get('name') in ('crypto-policies','fips-provider-so'): print('  requires',x.attrib)
   e.clear()
PY
